{
  "items": [
    {
      "title": "German Federal Election 2025 – Official Open Data",
      "url_or_doi": "https://www.bundeswahlleiterin.de/en/bundestagswahlen/2025/ergebnisse/opendata.html",
      "justification": "Official dataset published by Germany's Federal Returning Officer containing results of the 2025 Bundestag election. Includes votes by political party, electoral constituency, federal state, and national totals. Provides downloadable CSV and XML files, constituency boundaries, and geographic information. Highly relevant for studying Germany's electoral system, political representation, party competition, and voting patterns during the 2020s."
    },
    {
      "title": "German Federal Election 2021 – Official Election Results",
      "url_or_doi": "https://www.bundeswahlleiterin.de/bundestagswahlen/2021/ergebnisse.html",
      "justification": "Official results of Germany's 2021 federal parliamentary election. Contains information about party vote shares, constituency outcomes, electoral participation, and parliamentary representation. Useful for analyzing political developments, electoral competition, and changes in voter preferences between the 2021 and 2025 federal elections."
    },
    {
      "title": "German Bundestag – Parliamentary Open Data",
      "url_or_doi": "https://www.bundestag.de/services/opendata/",
      "justification": "Official open-data platform of the German federal parliament. Provides machine-readable parliamentary documents, plenary proceedings, voting records, and biographical information about members of parliament. Includes data covering the 2020s, making it especially valuable for studying legislative behavior, parliamentary organizations, political parties, and government accountability."
    },
    {
      "title": "German Bundestag – Political Party Financial Reports",
      "url_or_doi": "https://www.bundestag.de/parlament/praesidium/parteienfinanzierung/rechenschaftsberichte",
      "justification": "Official collection of financial disclosure reports submitted by German political parties. Includes reports covering the 2020s, documenting party income, expenditures, donations, and financial assets. Suitable for research into political organizations, party financing, political influence, and transparency in Germany's democratic system."
    },
    {
      "title": "GERDA – German Election Database",
      "url_or_doi": "https://www.german-elections.com/election-data/",
      "justification": "Research-oriented database providing German election results, geographic crosswalks, and contextual variables. Includes election data from the 2020s, with harmonized geographic boundaries facilitating comparisons across elections. Particularly useful for studying regional political differences, electoral geography, party support, and changes in political representation."
    },
    {
      "title": "Object-Centric and Traditional Event Data of the German Bundestag",
      "url_or_doi": "https://zenodo.org/records/16811928",
      "justification": "Open research dataset derived from Germany's parliamentary documentation and information system. Contains structured information about parliamentary documents, legislative procedures, procedural stages, and political activities involving the Bundestag and Bundesrat. Suitable for analyzing government decision-making, legislative workflows, parliamentary processes, and interactions among political institutions."
    },
    {
      "title": "GovData – Germany's National Open Government Data Portal",
      "url_or_doi": "https://data.gov.de/",
      "justification": "Germany's official national open-data portal, aggregating datasets from federal, state, and local public authorities. Provides access to administrative, institutional, governmental, and public-sector information, including datasets published during the 2020s. Useful for investigating German federalism, government organizations, public administration, and institutional transparency. This is a dataset discovery portal rather than a single dataset."
    },
    {
      "title": "German Election Results Since 1946 – Konrad Adenauer Foundation",
      "url_or_doi": "https://www.kas.de/en/web/wahlanalysen-und-gesellschaftsstudien/election-results-representative-election-statistics",
      "justification": "Historical election database covering German federal, European, and state parliamentary elections, including elections held during the 2020s. Provides party-level election results and comparative electoral statistics. Useful for examining the evolution of Germany's party system, political competition, electoral realignment, and regional voting patterns."
    },
    {
      "title": "Parteispendenwatch – German Political Party Donations",
      "url_or_doi": "https://parteispendenwatch.de/",
      "justification": "Public platform compiling information about donations to German political parties using official Bundestag disclosures. The underlying information is updated regularly and supports analysis of political donations, donor geography, party financing, and financial relationships between political organizations and private contributors during the 2020s."
    },
    {
      "title": "DonationWatch – German Political Donations Data",
      "url_or_doi": "https://donation.watch/de/germany/methodology",
      "justification": "Dataset initiative that collects, normalizes, and contextualizes officially disclosed political donations in Germany. Its coverage extends from 2010 into the 2020s. Relevant for studying political party financing, transparency, donor networks, and financial influence within Germany's political system. The linked methodology page explains the data sources and processing approach."
    }
  ]
}
